def total(values: list[float]) -> float:
    result = 0.0
    for value in values:
        result = result + value
    return result

def count_between(values: list[float], low: float, high: float) -> int:
    count = 0
    for value in values:
        if value >= low and value <= high:
            count += 1
    return count

def element(values: list[float], index: int) -> float:
    return values[index]

def composed_total(values: list[float]) -> float:
    return total(values)
